// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.concurrent.atomic.AtomicBoolean;

import org.codehaus.janino.SimpleCompiler;
import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.JaninoKernel;
import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelCancellation;
import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelCancelledException;
import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelContext;
import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelRuntime;
import org.junit.jupiter.api.Test;

/**
 * Pins the probe-deadline poll machinery: the cancellation flag's latch/deadline/extra-supplier semantics, the
 * stackless singleton thrown by {@link KernelRuntime#checkCancelled}, and — the integration risk of the emitter change
 * — that a kernel written in exactly the emitted poll pattern compiles in Janino's child classloader (public SPI
 * visibility of {@link KernelCancellation}), runs to completion untouched when no cancellation is bound, and aborts
 * within one mask window (1024 iterations) of a tripped deadline.
 */
class LmdbNativeKernelPollPointTest {

	@Test
	void cancellationLatchesOnDeadlineManualCancelAndExtraSupplier() {
		KernelCancellation expired = new KernelCancellation(System.nanoTime() - 1L);
		assertTrue(expired.cancelled(), "a past deadline cancels on the first poll");
		assertTrue(expired.cancelled(), "and latches");

		KernelCancellation future = new KernelCancellation(System.nanoTime() + 3_600_000_000_000L);
		assertFalse(future.cancelled(), "an hour-away deadline does not cancel");
		future.cancel();
		assertTrue(future.cancelled(), "manual cancel latches");

		AtomicBoolean group = new AtomicBoolean();
		KernelCancellation withExtra = new KernelCancellation(System.nanoTime() + 3_600_000_000_000L, group::get);
		assertFalse(withExtra.cancelled());
		group.set(true);
		assertTrue(withExtra.cancelled(), "a parallel group's cancelled flag folds in");
	}

	@Test
	void checkCancelledThrowsTheStacklessSingletonAndIgnoresNull() {
		KernelRuntime.checkCancelled(null);
		KernelCancellation live = new KernelCancellation(System.nanoTime() + 3_600_000_000_000L);
		KernelRuntime.checkCancelled(live);
		KernelCancellation tripped = new KernelCancellation(System.nanoTime() - 1L);
		KernelCancelledException thrown = assertThrows(KernelCancelledException.class,
				() -> KernelRuntime.checkCancelled(tripped));
		assertSame(KernelCancelledException.INSTANCE, thrown, "the exception is the shared stackless instance");
		assertEquals(0, thrown.getStackTrace().length, "stackless by construction");
	}

	@Test
	void aGeneratedStyleKernelPollsWithinOneMaskWindow() throws Exception {
		// Exactly the emitter's poll pattern: cancel/pollTick fields, bind from context, masked check in the loop.
		String source = "package org.eclipse.rdf4j.sail.lmdb.gen;\n"
				+ "import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.JaninoKernel;\n"
				+ "import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelCancellation;\n"
				+ "import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelContext;\n"
				+ "import org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelRuntime;\n"
				+ "public final class PollProbeKernel implements JaninoKernel {\n"
				+ "    private KernelCancellation cancel;\n"
				+ "    private int pollTick;\n"
				+ "    public long iterations;\n"
				+ "    public void bind(KernelContext context) {\n"
				+ "        cancel = context.cancellation;\n"
				+ "    }\n"
				+ "    public int fill(long[] out, int max) {\n"
				+ "        for (long i = 0L; i < 10_000_000L; i++) {\n"
				+ "            if ((++pollTick & 1023) == 0) { KernelRuntime.checkCancelled(cancel); }\n"
				+ "            iterations = i;\n"
				+ "        }\n"
				+ "        return 0;\n"
				+ "    }\n"
				+ "    public void close() {\n"
				+ "    }\n"
				+ "}\n";
		SimpleCompiler compiler = new SimpleCompiler();
		compiler.setParentClassLoader(JaninoKernel.class.getClassLoader());
		compiler.cook(source);
		Class<?> kernelClass = compiler.getClassLoader().loadClass("org.eclipse.rdf4j.sail.lmdb.gen.PollProbeKernel");

		KernelContext plain = new KernelContext(null, new long[0], new long[0], null);
		JaninoKernel untouched = (JaninoKernel) kernelClass.getDeclaredConstructor().newInstance();
		untouched.bind(plain);
		assertEquals(0, untouched.fill(new long[0], 0), "a null cancellation never aborts");

		KernelContext probed = new KernelContext(null, new long[0], new long[0], null)
				.withCancellation(new KernelCancellation(System.nanoTime() - 1L));
		JaninoKernel probedKernel = (JaninoKernel) kernelClass.getDeclaredConstructor().newInstance();
		probedKernel.bind(probed);
		assertThrows(KernelCancelledException.class, () -> probedKernel.fill(new long[0], 0));
		long iterations = (Long) kernelClass.getField("iterations").get(probedKernel);
		assertTrue(iterations < 1024, "the tripped deadline must abort within one mask window, ran " + iterations);
	}
}
